    .option("--title <title>", "Update task title")
    .option("--spec-ref <ref>", "Link to spec item")
    .option(
      "--meta-ref <ref>",
      "Link to meta item (workflow, agent, or convention)",
    )
    .option("--priority <n>", "Set priority (1-5)")
    .option("--slug <slug>", "Add a slug alias")
